<script setup lang="ts">
import {paperThemes} from '../../core/figureThemes'
import {textRoleLabels} from '../../core/paperStyle'
import {computed,ref} from 'vue'
import {Box,Button,Disclosure,DisclosureTrigger,Field,Footer,Header,Heading,Modal,ModalBody,Select,Text,TextArea,TextField} from '@fastrd/ui-vue'
import IconButton from '../ui/IconButton.vue'
import {useEditor} from '../../composables/useEditor'
import {captureStyleAsset,styleFromCompositionDraft,applyStyleAsset,styleAssetSchema,type StyleAsset} from '../../core/styleAsset'
import {containerSurfaceOptions} from '../../core/containerSurface'
import {clone,styles} from '../../core/model'
import {colorPalettes,fontFamilies,paletteById} from '../../data/materials'
import FigureRenderer from '../figure/FigureRenderer'
import {checkFigureText} from '../../core/figureTextCheck'
import StyleAssetSummary from './StyleAssetSummary.vue'
import ThemeColorPicker from './ThemeColorPicker.vue'
import ColorMapEditor from './ColorMapEditor.vue'
import StyleLinePresetEditor from './StyleLinePresetEditor.vue'
import {sketchStyleIds,sketchStyleLabels} from '../../core/sketchStyle'
import {canColorContainer} from '../../core/containerColor'
const sketchOptions=[{value:'',label:'默认 Rough.js'},...sketchStyleIds.map(id=>({value:id,label:sketchStyleLabels[id]}))]
const sizeFields=[{key:'headingSize',label:'模块标题',min:14,max:26,step:1},{key:'bodySize',label:'正文',min:12,max:22,step:1},{key:'captionSize',label:'注释',min:10,max:18,step:1},{key:'containerHeadingSize',label:'分区标题',min:16,max:26,step:1},{key:'radius',label:'模块圆角',min:2,max:24,step:1},{key:'padding',label:'模块内边距',min:4,max:20,step:1},{key:'strokeWidth',label:'边框线宽',min:.5,max:3,step:.1}] as const
function choosePaperTheme(variant:string){const theme=paperThemes.find(t=>t.paperTheme?.variant===variant)!;Object.assign(form.value,{paperTheme:clone(theme.paperTheme),fontFamily:theme.fontFamily,paletteId:theme.paletteId,sketchStyle:theme.sketchStyle,roughness:theme.roughness,preset:theme.preset})}
const editor=useEditor(),context=editor.styleDialog.value!
const source=context.kind==='plan'?styleFromCompositionDraft(context.record):context.kind==='edit'?editor.styleLibrary.assets.value.find(a=>a.id===context.id):captureStyleAsset(editor.figure.value,editor.currentContainer.value.id)
const form=ref<StyleAsset>(clone(source??captureStyleAsset(editor.figure.value))),tags=ref(form.value.tags.join('、')),query=ref(''),typography=ref(true),error=ref(''),targetId=editor.currentContainer.value.id
const validation=computed(()=>styleAssetSchema.safeParse({...form.value,tags:tags.value.split(/[,，、\n]/).map(v=>v.trim()).filter(Boolean)}))
const asset=computed(()=>validation.value.success?validation.value.data:null)
const invalidReason=computed(()=>validation.value.success?'':validation.value.error.issues.some(issue=>issue.path.includes('paperTheme'))?'请检查主题尺寸范围，并满足标题 ≥ 正文 ≥ 注释。':'请填写名称，并检查说明、标签、来源数量（最多 12 条）及素材容量（最多 60 KB）。')
const options=computed(()=>{const terms=query.value.toLocaleLowerCase().trim().split(/\s+/).filter(Boolean),found=colorPalettes.filter(p=>terms.every(t=>[p.title,p.id,p.family,...p.tags,...p.colors].join(' ').toLocaleLowerCase().includes(t))).slice(0,24);return[...new Map([paletteById.get(form.value.paletteId)!,...found].map(p=>[p.id,p])).values()].map(p=>({value:p.id,label:p.title}))})
const preview=computed(()=>{if(!asset.value)return null;try{return applyStyleAsset(editor.figure.value,asset.value,targetId,typography.value)}catch{return null}})
const mappingBasis=computed(()=>{try{return applyStyleAsset(editor.figure.value,{...form.value,colorMap:undefined},targetId,false).figure}catch{return editor.figure.value}})
const textCheck=computed(()=>preview.value?checkFigureText(preview.value.figure):null)
function save(apply=false){if(!asset.value)return;try{const saved=editor.styleLibrary.save({...asset.value,updatedAt:new Date().toISOString()});if(apply)editor.applySavedStyle(saved,typography.value);else editor.notice.value=`已保存风格${saved.name}`;editor.styleDialog.value=null}catch(e){error.value=(e as Error).message}}
function setPalette(id:string){form.value.paletteId=id;if((form.value.colorIndex??0)>=paletteById.get(id)!.colors.length)delete form.value.colorIndex}
</script>
<template>
  <Modal :open="true" size="xl" label="保存与预览风格" class="style-asset-dialog" @close="editor.styleDialog.value=null">
    <Header><Box><Heading>{{ context.kind==='edit'?'编辑风格素材':'保存风格素材' }}</Heading><Text class="muted-caption">预览当前容器；保留几何、手工字号和图表编码，可明确保存连线规范。</Text></Box><IconButton icon="close" label="关闭风格编辑" @click="editor.styleDialog.value=null" /></Header>
    <ModalBody><Box class="style-asset-editor"><Box class="style-asset-form"><Text v-if="context.kind==='plan'" class="muted-caption">保存方案的全图风格；组件局部映射请在选中对应容器后单独保存。</Text><Field><Text>风格名称</Text><TextField v-model="form.name" maxlength="100" aria-label="风格名称" /></Field><Field><Text>说明</Text><TextArea v-model="form.description" rows="2" maxlength="500" aria-label="风格说明" /></Field><Field><Text>标签</Text><TextField v-model="tags" maxlength="300" aria-label="风格标签" placeholder="科研、柔和、手绘…" /></Field><Field><Text>容器样式</Text><Select :value="form.preset" :options="styles.map(s=>({value:s.id,label:s.name}))" aria-label="风格容器样式" @change="form.preset=$event as StyleAsset['preset']" /></Field><Field><Text>查找配色</Text><TextField v-model="query" type="search" aria-label="查找风格配色" placeholder="名称、科研、柔和或色号" /></Field><Select :value="form.paletteId" :options="options" aria-label="风格配色" @change="setPalette($event)" /><Field><Text>默认主题色</Text><ThemeColorPicker v-model="form.colorIndex" :palette-id="form.paletteId" label="风格默认主题色" /></Field><Disclosure v-if="canColorContainer(editor.figure.value,targetId)"><DisclosureTrigger size="xs">编辑风格颜色映射</DisclosureTrigger><ColorMapEditor v-model="form.colorMap" :figure="mappingBasis" :container-id="targetId" :target-palette-id="form.paletteId" /></Disclosure><Field><Text>容器填充</Text><Select :value="form.surface??'plain'" :options="containerSurfaceOptions" aria-label="风格容器填充" @change="form.surface=$event as StyleAsset['surface']" /></Field><Field v-if="form.preset==='sketch'"><Text>手绘笔触</Text><Select :value="form.sketchStyle??''" :options="sketchOptions" aria-label="风格手绘笔触" @change="form.sketchStyle=($event||undefined) as typeof form.sketchStyle" /></Field><Field v-if="form.preset==='sketch'"><Text>起伏强度</Text><TextField v-model.number="form.roughness" type="number" min="0" max="2" step="0.1" aria-label="风格起伏强度" /></Field><Field><Text>视觉体系</Text><Select :value="form.designSystem??'legacy'" :options="[{value:'paper',label:'论文插图 · 角色样式'},{value:'legacy',label:'独立字体与容器皮肤'}]" aria-label="风格视觉体系" @change="form.designSystem=$event as 'paper'|'legacy'" /></Field><template v-if="form.designSystem==='paper'"><Field><Text>主题基础</Text><Select :value="form.paperTheme?.variant??'soft'" :options="paperThemes.map(t=>({value:t.paperTheme!.variant,label:t.name}))" aria-label="风格论文主题" @change="choosePaperTheme" /></Field><Disclosure><DisclosureTrigger size="xs">主题尺寸与边界</DisclosureTrigger><Button v-if="!form.paperTheme" size="sm" @click="choosePaperTheme('soft')">启用主题尺寸</Button><Box v-if="form.paperTheme" class="paper-theme-size-grid"><Field v-for="field in sizeFields" :key="field.key"><Text>{{ field.label }}</Text><TextField v-model.number="form.paperTheme[field.key]" type="number" :min="field.min" :max="field.max" :step="field.step" :aria-label="`主题${field.label}`" /></Field></Box><Text class="muted-caption">画板单位，整体缩放时同比变化；标题 ≥ 正文 ≥ 注释。已有手工字号保持，空间不足请调整布局。</Text></Disclosure><Field v-for="(roleName,role) in textRoleLabels" :key="role"><Text>{{ roleName }}字体</Text><Select :value="form.fontRoles?.[role]??''" :options="[{value:'',label:'使用默认角色字体'},...fontFamilies.map(value=>({value,label:value}))]" :aria-label="`${roleName}字体`" @change="form.fontRoles={...form.fontRoles,[role]:$event||undefined}" /></Field></template><Field><Text>字体</Text><Select :value="form.fontFamily" :options="fontFamilies.map(value=>({value,label:value}))" aria-label="风格字体" @change="form.fontFamily=$event as StyleAsset['fontFamily']" /></Field><StyleLinePresetEditor v-model="form.lineStyle" :figure="editor.figure.value" :container-id="targetId" /><Field><Text>颜色与图示的使用说明</Text><TextArea v-model="form.guide" rows="4" maxlength="1200" aria-label="风格使用说明" placeholder="说明具体对象的轮廓、颜色和线型含义、主视觉及阅读轴；减少重复标题与套框，保留可读文字。" /></Field><Field class="checkbox-field"><TextField v-model="typography" type="checkbox" aria-label="预览时统一字体" /><Text>采用主题字体和默认字号，保留手工字号；图表和定位字形保持</Text></Field><Box v-if="form.references.length" class="style-source-choices"><Text>样式参考来源（最多 12 条；可精简，原方案输入记录仍保留）</Text><Box v-for="(reference,index) in form.references" :key="reference.sha256"><Text>{{ reference.title }}</Text><Button size="xs" variant="quiet" :aria-label="`移除风格来源 ${index+1}`" @click="form.references=form.references.filter((_,i)=>i!==index)">移除</Button></Box></Box><Text v-if="!asset" role="alert" class="error-text">{{ invalidReason }}</Text><Text v-if="error" role="alert" class="error-text">{{ error }}</Text></Box><Box class="style-asset-preview"><Heading>当前图件预览</Heading><FigureRenderer v-if="preview" :figure="preview.figure" /><Text v-if="preview" class="muted-caption">字体调整 {{ preview.use.textNodes }} 个对象，保留 {{ preview.use.skippedTextNodes }} 个图表 / 定位文字对象。内部容器与手工颜色可单独覆盖。</Text><Text v-if="preview?.use.lines" class="muted-caption">连线规范：可处理 {{ preview.use.lines.total }} 条，调整 {{ preview.use.lines.changed }} 条，保留 {{ preview.use.lines.skipped }} 条。</Text><Text v-if="!preview" class="placement-message">当前设置无法预览，请检查风格和图件来源容量。</Text><Text v-if="textCheck" class="muted-caption">文字检查：{{ textCheck.total }} 项；应用后仍可逐项调整。</Text><StyleAssetSummary v-if="asset" :asset="asset" /></Box></Box></ModalBody>
    <Footer><Button @click="editor.styleDialog.value=null">取消</Button><Button :disabled="!asset" @click="save()">保存到风格库</Button><Button variant="primary" :disabled="!preview" @click="save(true)">保存并应用</Button></Footer>
  </Modal>
</template>
